B.Q1=new A.am(B.cD,["Trung t\xe2m Tr\xed Hu\u1ec7 (Crown)","Tuy\u1ebfn t\xf9ng (Pineal Gland)","\xc1p l\u1ef1c t\u01b0 duy & C\u1ea3m h\u1ee9ng","Ngu\u1ed3n c\u1ea3m h\u1ee9ng b\u1ec1n b\u1ec9 t\u1eeb b\xean trong, \xe1p l\u1ef1c gi\u1ea3i quy\u1ebft c\xe1c c\xe2u h\u1ecfi l\u1edbn c\u1ee7a cu\u1ed9c \u0111\u1eddi.","M\u1edf \u0111\xf3n nh\u1eadn c\u1ea3m h\u1ee9ng t\u1eeb mu\xf4n n\u01a1i, linh ho\u1ea1t nh\u01b0ng d\u1ec5 b\u1ecb \xe1p l\u1ef1c gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 c\u1ee7a ng\u01b0\u1eddi kh\xe1c.","T\xf4i c\xf3 \u0111ang c\u1ed1 g\u1eafng tr\u1ea3 l\u1eddi nh\u1eefng c\xe2u h\u1ecfi kh\xf4ng ph\u1ea3i c\u1ee7a m\xecnh kh\xf4ng?"],t.l)
B.Q2=new A.am(B.cD,["Trung t\xe2m Tu\u1ec7 Nh\xe3n (Ajna)","Tuy\u1ebfn y\xean (Pituitary Gland)","Nh\u1eadn th\u1ee9c tinh th\u1ea7n & X\u1eed l\xfd th\xf4ng tin","T\u01b0 duy ki\xean \u0111\u1ecbnh, c\xf3 c\u1ea5u tr\xfac ph\xe2n t\xedch nh\u1ea5t qu\xe1n, quan \u0111i\u1ec3m v\u1eefng ch\xe3i nh\u01b0ng c\xf3 th\u1ec3 b\u1ea3o th\u1ee7.","T\u01b0 duy m\u1edf, d\u1ec5 nh\xecn nh\u1eadn \u0111a chi\u1ec1u kh\xf4ng ph\xe1n x\xe9t, kh\xf4ng c\u1ea7n t\u1ecf ra lu\xf4n ch\u1eafc ch\u1eafn.","T\xf4i c\xf3 \u0111ang c\u1ed1 thuy\u1ebft ph\u1ee5c m\u1ecdi ng\u01b0\u1eddi r\u1eb1ng t\xf4i lu\xf4n lu\xf4n ch\u1eafc ch\u1eafn kh\xf4ng?"],t.l)
B.Q_=new A.am(B.cD,["Trung t\xe2m Tu\u1ec7 Ng\xf4n (Throat)","Tuy\u1ebfn gi\xe1p & C\u1eadn gi\xe1p","Bi\u1ec3u hi\u1ec7n & Hi\u1ec7n th\u1ef1c h\xf3a","Gi\u1ecdng n\xf3i nh\u1ea5t qu\xe1n, kh\u1ea3 n\u0103ng bi\u1ebfn \xfd t\u01b0\u1edfng v\xe0 n\u0103ng l\u01b0\u1ee3ng th\xe0nh h\xe0nh \u0111\u1ed9ng th\u1ef1c t\u1ebf.","Giao ti\u1ebfp linh ho\u1ea1t t\xf9y \u0111\u1ed1i t\u01b0\u1ee3ng, n\xf3i chuy\u1ec7n c\xf3 tr\u1ecdng l\u01b0\u1ee3ng khi \u0111\u01b0\u1ee3c m\u1eddi ph\xe1t bi\u1ec3u.","T\xf4i c\xf3 \u0111ang c\u1ed1 g\u1eafng thu h\xfat s\u1ef1 ch\xfa \xfd b\u1eb1ng c\xe1ch n\xf3i qu\xe1 nhi\u1ec1u kh\xf4ng?"],t.l)
B.Q3=new A.am(B.cD,["Trung t\xe2m Th\u01b0\u1ee3ng Ng\xe3 (G-Center)","Gan & Tu\u1ea7n ho\xe0n m\xe1u","B\u1ea3n s\u1eafc, T\xecnh y\xeau & H\u01b0\u1edbng \u0111i cu\u1ed9c \u0111\u1eddi","B\u1ea3n s\u1eafc v\u1eefng ch\xe3i nh\u01b0 m\u1ed9t chi\u1ebfc la b\xe0n n\u1ed9i t\xe2m, \u0111\u1ecbnh h\u01b0\u1edbng cu\u1ed9c \u0111\u1eddi \u1ed5n \u0111\u1ecbnh v\xe0 ki\xean \u0111\u1ecbnh.","B\u1ea3n s\u1eafc linh ho\u1ea1t, \u0111\u1ed5i m\u1edbi theo m\xf4i tr\u01b0\u1eddng v\xe0 ng\u01b0\u1eddi \u0111\u1ed3ng h\xe0nh, tr\u1ea3i nghi\u1ec7m nhi\u1ec1u con \u0111\u01b0\u1eddng.","T\xf4i c\xf3 \u0111ang \xe1m \u1ea3nh t\xecm ki\u1ebfm xem t\xf4i l\xe0 ai v\xe0 t\xf4i \u0111ang \u0111i v\u1ec1 \u0111\xe2u kh\xf4ng?"],t.l)
B.Q6=new A.am(B.cD,["Trung t\xe2m T\xe2m Ng\xe3 / \xdd Ch\xed (Heart/Ego)","Tim, Tuy\u1ebfn \u1ee9c, T\xfai m\u1eadt, D\u1ea1 d\xe0y","\u0110\u1ed9ng c\u01a1 \xdd ch\xed & Gi\xe1 tr\u1ecb b\u1ea3n th\xe2n","\xdd ch\xed s\u1eaft \u0111\xe1, quy\u1ebft t\xe2m cao, kh\u1ea3 n\u0103ng th\u1ef1c hi\u1ec7n cam k\u1ebft v\xe0 qu\u1ea3n l\xfd t\xe0i nguy\xean v\u1eadt ch\u1ea5t.","Gi\xe1 tr\u1ecb b\u1ea3n th\xe2n l\xe0 v\u1ed1n c\xf3 kh\xf4ng c\u1ea7n ch\u1ee9ng minh; kh\xf4ng n\xean h\u1ee9a h\u1eb9n r\xe0ng bu\u1ed9c \xfd ch\xed.","T\xf4i c\xf3 \u0111ang c\u1ea3m th\u1ea5y m\xecnh ph\u1ea3i n\u1ed7 l\u1ef1c ch\u1ee9ng minh gi\xe1 tr\u1ecb b\u1ea3n th\xe2n v\u1edbi ai \u0111\xf3 kh\xf4ng?"],t.l)
B.Q0=new A.am(B.cD,["Trung t\xe2m Th\xe1i D\u01b0\u01a1ng (Solar Plexus)","Th\u1eadn, H\u1ec7 th\u1ea7n kinh","\u0110\u1ed9ng c\u01a1 & Nh\u1eadn th\u1ee9c C\u1ea3m x\xfac","Ph\xe1t ra nh\u1eefng l\xe0n s\xf3ng c\u1ea3m x\xfac t\u1ef1 nhi\xean; c\u1ea7n ki\xean nh\u1eabn ch\u1edd c\u1ea3m x\xfac l\u1eafng \u0111\u1ecdng \u0111\u1ec3 s\xe1ng su\u1ed1t.","Khu\u1ebfch \u0111\u1ea1i c\u1ea3m x\xfac t\u1eeb ng\u01b0\u1eddi kh\xe1c; l\xe0 t\u1ea5m g\u01b0\u01a1ng th\u1ea5u c\u1ea3m nh\u01b0ng c\u1ea7n gi\u1eef ranh gi\u1edbi c\u1ea3m x\xfac an to\xe0n.","T\xf4i c\xf3 \u0111ang n\xe9 tr\xe1nh s\u1ef1 th\u1eadt v\xe0 \u0111\u1ed1i \u0111\u1ea7u v\xec s\u1ee3 l\xe0m ng\u01b0\u1eddi kh\xe1c bu\u1ed3n kh\xf4ng?"],t.l)
B.Q5=new A.am(B.cD,["Trung t\xe2m Sinh Kh\xed / \u0110an \u0110i\u1ec1n (Sacral)","C\u01a1 quan sinh s\u1ea3n","\u0110\u1ed9ng c\u01a1 L\u1ef1c s\u1ed1ng b\u1ec1n b\u1ec9","Ngu\u1ed3n pin l\xe0m vi\u1ec7c v\xf4 t\u1eadn khi \u0111\u01b0\u1ee3c l\xe0m \u0111i\u1ec1u m\xecnh th\xedch; ph\u1ea3n h\u1ed3i qua \xe2m thanh d\u1ea1 d\xe0y (\u1eea h\u1ee9/\u1eea \u1eeb).","Kh\xf4ng c\xf3 ngu\u1ed3n n\u0103ng l\u01b0\u1ee3ng li\xean t\u1ee5c; c\u1ea7n bi\u1ebft \u0111i\u1ec3m d\u1eebng \u0111\u1ec3 ngh\u1ec9 ng\u01a1i n\u1ea1p l\u1ea1i, tr\xe1nh ki\u1ec7t s\u1ee9c.","T\xf4i c\xf3 bi\u1ebft khi n\xe0o l\xe0 \u0111\u1ee7 \u0111\u1ec3 d\u1eebng l\u1ea1i v\xe0 ngh\u1ec9 ng\u01a1i kh\xf4ng?"],t.l)
B.Q4=new A.am(B.cD,["Trung t\xe2m Sinh Gi\xe1c / L\xe1ch (Spleen)","H\u1ec7 mi\u1ec5n d\u1ecbch, H\u1ec7 b\u1ea1ch huy\u1ebft, L\xe1ch","Nh\u1eadn th\u1ee9c Tr\u1ef1c gi\xe1c Sinh t\u1ed3n","Tr\u1ef1c gi\xe1c nh\u1ea1y b\xe9n trong kho\u1ea3nh kh\u1eafc t\u1ee9c th\u1eddi, s\u1ee9c \u0111\u1ec1 kh\xe1ng t\u1ed1t, c\u1ea3nh b\xe1o nguy hi\u1ec3m nhanh ch\xf3ng.","Nh\u1ea1y c\u1ea3m v\u1edbi s\u1ee9c kh\u1ecfe ng\u01b0\u1eddi kh\xe1c; d\u1ec5 b\xe1m v\xedu v\xe0o m\u1ed1i quan h\u1ec7 \u0111\u1ed9c h\u1ea1i v\xec c\u1ea3m gi\xe1c an to\xe0n quen thu\u1ed9c.","T\xf4i c\xf3 \u0111ang n\xedu gi\u1eef \u0111i\u1ec1u g\xec kh\xf4ng c\xf2n l\xe0nh m\u1ea1nh ch\u1ec9 v\xec s\u1ee3 h\xe3i kh\xf4ng?"],t.l)
B.PZ=new A.am(B.cD,["Trung t\xe2m G\u1ed1c (Root)","Tuy\u1ebfn th\u01b0\u1ee3ng th\u1eadn (Adrenaline)","\xc1p l\u1ef1c & \u0110\u1ed9ng c\u01a1 Sinh t\u1ed3n","Ch\u1ecbu \u0111\u1ef1ng c\u0103ng th\u1eb3ng t\u1ed1t, bi\u1ebfn \xe1p l\u1ef1c cu\u1ed9c s\u1ed1ng th\xe0nh \u0111\u1ed9ng l\u1ef1c h\xe0nh \u0111\u1ed9ng \u1ed5n \u0111\u1ecbnh.","D\u1ec5 b\u1ecb cu\u1ed1n theo \xe1p l\u1ef1c v\xe0 s\u1ef1 g\u1ea5p g\xe1p c\u1ee7a ng\u01b0\u1eddi kh\xe1c; c\u1ea7n h\u1ecdc c\xe1ch th\u1ea3 l\u1ecfng th\u01b0 th\xe1i.","T\xf4i c\xf3 \u0111ang v\u1ed9i v\xe3 l\xe0m m\u1ecdi vi\u1ec7c ch\u1ec9 \u0111\u1ec3 gi\u1ea3i ph\xf3ng \xe1p l\u1ef1c kh\xf4ng?"],t.l)
